'use client';

import React, { useState } from 'react';
import { Card, Button, Input } from '@/components/ui/base';
import { LineChart, AlertTriangle, CheckCircle, Edit2, Save } from 'lucide-react';
import { useTransactions } from '@/lib/transaction-context';

export default function BudgetsPage() {
  const { transactions, stats, budgetLimit, updateBudgetLimit } = useTransactions();
  const [isEditing, setIsEditing] = useState(false);
  const [newLimit, setNewLimit] = useState(budgetLimit.toString());

  const handleSaveLimit = () => {
    const val = parseFloat(newLimit);
    if (!isNaN(val) && val > 0) {
      updateBudgetLimit(val);
      setIsEditing(false);
    }
  };

  // Key Insight Generation
  const insight = React.useMemo(() => {
    const expenses = transactions.filter(t => t.type === 'Expense');
    if (expenses.length === 0) return { category: 'None', amount: 0 };
    
    const catTotals: Record<string, number> = {};
    expenses.forEach(t => {
      catTotals[t.category] = (catTotals[t.category] || 0) + t.amount;
    });
    
    const topCategory = Object.keys(catTotals).reduce((a, b) => catTotals[a] > catTotals[b] ? a : b);
    return { category: topCategory, amount: catTotals[topCategory] };
  }, [transactions]);

  // Calculate budgets per category (Auto-generated 20% of income as mock limit per category)
  const categoryBudgets = React.useMemo(() => {
    const expenses = transactions.filter(t => t.type === 'Expense');
    const categories = Array.from(new Set(expenses.map(t => t.category)));
    
    return categories.map(cat => {
      const spent = expenses.filter(t => t.category === cat).reduce((acc, t) => acc + t.amount, 0);
      const limit = 500; // Mock limit per category
      return {
        category: cat,
        spent,
        limit,
        percent: Math.min((spent / limit) * 100, 100)
      };
    });
  }, [transactions]);

  const recommendedLimit = budgetLimit || (stats.totalIncome * 0.8);
  const globalPercent = Math.min((stats.totalExpense / (recommendedLimit || 1)) * 100, 100);

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-4xl font-bold text-gray-900">Smart Budgets</h1>
        <p className="text-lg text-gray-500">AI-driven budget recommendations based on your income.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {/* Main Smart Budget Card */}
        <Card className="md:col-span-2 p-8 bg-gray-900 text-white border-none">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-2">
              <LineChart className="text-green-400" />
              <h3 className="text-2xl font-bold">Overall Monthly Budget</h3>
            </div>
            <Button 
                variant="ghost" 
                size="sm" 
                className="text-gray-400 hover:text-white"
                onClick={() => {
                    if (isEditing) handleSaveLimit();
                    else {
                        setNewLimit(recommendedLimit.toString());
                        setIsEditing(true);
                    }
                }}
            >
                {isEditing ? <Save size={20} /> : <Edit2 size={20} />}
            </Button>
          </div>
          
          <div className="space-y-6">
            <div className="bg-gray-800 p-8 rounded-xl">
              <div className="flex justify-between items-end mb-2">
                <div>
                   <span className="text-gray-400 text-base">
                       {budgetLimit > 0 ? "Your Custom Budget Limit" : "Recommended Safe Limit (80% Income)"}
                   </span>
                   {isEditing ? (
                       <div className="flex items-center gap-2 mt-2">
                           <span className="text-2xl text-white">₹</span>
                           <Input 
                               value={newLimit} 
                               onChange={e => setNewLimit(e.target.value)}
                               className="bg-gray-700 text-white border-none text-xl w-48"
                               type="number"
                           />
                       </div>
                   ) : (
                       <p className="text-4xl font-bold text-white">₹{recommendedLimit.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
                   )}
                </div>
                <div className="text-right">
                   <span className="text-gray-400 text-base">Current Spend</span>
                   <p className="text-2xl font-bold text-white">₹{stats.totalExpense.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
                </div>
              </div>
              
              <div className="w-full bg-gray-700 rounded-full h-4 mt-4">
                <div 
                  className={`h-4 rounded-full transition-all duration-500 ${globalPercent > 90 ? 'bg-red-500' : 'bg-green-500'}`}
                  style={{ width: `${globalPercent}%` }}
                ></div>
              </div>
              
              <div className="flex items-start gap-3 mt-4">
                 {globalPercent > 90 ? <AlertTriangle className="text-red-500 shrink-0" /> : <CheckCircle className="text-green-500 shrink-0" />}
                 <p className="text-base text-gray-300">
                    {stats.totalExpense > recommendedLimit 
                        ? "Warning: You have exceeded your budget limit. Immediate cutbacks recommended." 
                        : "You are within the safe spending limit. Good job maintaining financial health."}
                  </p>
              </div>
            </div>

            <div className="bg-gray-800 p-6 rounded-lg border-l-4 border-purple-500">
                 <p className="text-base text-gray-300 mb-1 font-medium">FinBERT Insight:</p>
                  <p className="text-base text-gray-300">
                    {insight.category !== 'None' ? (
                        <>
                        "High spending concentration detected in <strong>{insight.category}</strong> (₹{insight.amount.toLocaleString('en-IN')}). This accounts for {Math.round((insight.amount / stats.totalExpense) * 100)}% of your total expenses."
                        </>
                    ) : (
                        "Start adding transactions to get AI insights."
                    )}
                  </p>
            </div>
          </div>
        </Card>

        {/* Category Limits */}
        <Card className="p-8 h-fit">
          <h3 className="text-xl font-bold mb-4">Category Limits</h3>
          <div className="space-y-6">
            {categoryBudgets.map((item) => (
              <div key={item.category}>
                <div className="flex justify-between text-base mb-1">
                  <span className="font-medium">{item.category}</span>
                  <span className="text-gray-500">₹{item.spent.toLocaleString('en-IN')} / ₹{item.limit.toLocaleString('en-IN')}</span>
                </div>
                <div className="w-full bg-gray-100 rounded-full h-2">
                  <div 
                    className={`h-2 rounded-full ${item.percent > 100 ? 'bg-red-500' : 'bg-blue-500'}`} 
                    style={{ width: `${item.percent}%` }}
                  ></div>
                </div>
              </div>
            ))}
            {categoryBudgets.length === 0 && <p className="text-gray-500 text-sm">No expenses recorded yet.</p>}
          </div>
          <Button variant="outline" className="w-full mt-6">Adjust Limits</Button>
        </Card>
      </div>
    </div>
  );
}
